mapper.select:
select count(1)
  from margin_stock_detail
 where deleted_at is null
   and trade_date = #{tradeDate}

   and exchange = #{exchange}


   and exists (
        select 1
          from ths_industry_constituent_snapshot c
         where c.deleted_at is null
           and c.industry_code = #{industryCode}
           and c.stock_code = margin_stock_detail.stock_code
           and c.snapshot_date = coalesce(
               (
                   select max(c1.snapshot_date)
                     from ths_industry_constituent_snapshot c1
                    where c1.deleted_at is null
                      and c1.snapshot_date <= #{tradeDate}
               ),
               (
                   select max(c2.snapshot_date)
                     from ths_industry_constituent_snapshot c2
                    where c2.deleted_at is null
               )
           )
   )
